// Test-only module hooks (node:module register) that let `node --test` import
// app modules written for Vite, without changing them:
//
//  - `import.meta.env` (Vite-only) is defined for modules under src/, from
//    globalThis.__VITE_ENV__ (default { BASE_URL: "/" });
//  - lib/dataVersion.js (generated by scripts/split-data.mjs, gitignored) is
//    replaced by a fixed stub, so tests never depend on a local data build;
//  - the Pagefind engine (`<BASE_URL>pagefind/pagefind.js`) is a stub that
//    delegates to globalThis.__fakePagefind;
//  - extensionless relative imports ("../lib/x") resolve to x.js, as in Vite;
//  - `data.aliases` ({ specifier: url }) replaces whole packages (e.g. react).
//
// Nothing in the app imports this file, so it never reaches the bundle.
// Usage, before the module under test is imported (dynamically):
//   register("./testing/viteNodeHooks.mjs", import.meta.url, { data: { aliases } });

export const TEST_DATA_VERSION = "test-v1";
export const TEST_FULL_BUCKETS = 64;

const js = (src) => `data:text/javascript,${encodeURIComponent(src)}`;

const DATA_VERSION_URL = js(
  `export const DATA_VERSION = ${JSON.stringify(TEST_DATA_VERSION)}; export const FULL_BUCKETS = ${TEST_FULL_BUCKETS};`
);
const PAGEFIND_URL = js(
  [
    "const pf = () => globalThis.__fakePagefind;",
    "export const options = (o) => pf().options(o);",
    "export const init = () => pf().init();",
    "export const search = (q) => pf().search(q);",
  ].join("\n")
);
// One line, prepended without a newline, so stack-trace line numbers stay right.
const ENV_PRELUDE = 'import.meta.env = globalThis.__VITE_ENV__ ?? { BASE_URL: "/" }; ';

let aliases = {};
export function initialize(data) {
  aliases = data?.aliases ?? {};
}

export async function resolve(specifier, context, next) {
  if (Object.hasOwn(aliases, specifier)) return { url: aliases[specifier], shortCircuit: true };
  const parent = context.parentURL ?? "";
  if (specifier === "./dataVersion.js" && /\/src\/lib\/[^/]+$/.test(parent.split("?")[0])) {
    return { url: DATA_VERSION_URL, shortCircuit: true };
  }
  if (/(^|\/)pagefind\/pagefind\.js$/.test(specifier)) return { url: PAGEFIND_URL, shortCircuit: true };
  try {
    return await next(specifier, context);
  } catch (err) {
    if (err?.code === "ERR_MODULE_NOT_FOUND" && /^\.{1,2}\//.test(specifier) && !/\.[cm]?jsx?$/.test(specifier)) {
      return next(`${specifier}.js`, context);
    }
    throw err;
  }
}

export async function load(url, context, next) {
  const result = await next(url, context);
  if (url.startsWith("file:") && /\/src\//.test(url) && result.format === "module") {
    const source = String(result.source);
    if (source.includes("import.meta.env")) return { ...result, source: ENV_PRELUDE + source, shortCircuit: true };
  }
  return result;
}
